// === ESTRUCTURA DEL PATRÓN VISITOR ===

// 1. Interfaz Visitor (método por cada tipo de elemento)
interface ShapeVisitor {
  visitCircle(circle: Circle): string;
  visitRectangle(rectangle: Rectangle): string;
  visitTriangle(triangle: Triangle): string;
}

// 2. Elementos con accept()
interface Shape {
  accept(visitor: ShapeVisitor): string;
  area(): number;
}

class Circle implements Shape {
  constructor(public radius: number) {}

  accept(visitor: ShapeVisitor): string {
    return visitor.visitCircle(this); // Despachación 1
  }

  area(): number {
    return Math.PI * this.radius ** 2;
  }
}

class Rectangle implements Shape {
  constructor(public width: number, public height: number) {}

  accept(visitor: ShapeVisitor): string {
    return visitor.visitRectangle(this);
  }

  area(): number {
    return this.width * this.height;
  }
}

// 3. Visitors Concretos
class SVGExporter implements ShapeVisitor {
  visitCircle(circle: Circle): string {
    return `<circle r="${circle.radius}" />`;
  }

  visitRectangle(rect: Rectangle): string {
    return `<rect width="${rect.width}" height="${rect.height}" />`;
  }

  visitTriangle(tri: Triangle): string {
    return `<polygon points="${tri.points}" />`;
  }
}

class JSONExporter implements ShapeVisitor {
  visitCircle(circle: Circle): string {
    return JSON.stringify({ type: 'circle', radius: circle.radius });
  }

  visitRectangle(rect: Rectangle): string {
    return JSON.stringify({ type: 'rectangle', width: rect.width, height: rect.height });
  }

  visitTriangle(tri: Triangle): string {
    return JSON.stringify({ type: 'triangle', points: tri.points });
  }
}

// Uso:
const shapes: Shape[] = [new Circle(5), new Rectangle(4, 6)];
const svgVisitor = new SVGExporter();
shapes.forEach(s => console.log(s.accept(svgVisitor)));
// <circle r="5" />
// <rect width="4" height="6" />

