// 1. Interfaz Visitor
interface ShapeVisitor {
  visitCircle(circle: Circle): string;
  visitRectangle(rectangle: Rectangle): string;
}

// 2. Elementos con accept()
interface Shape {
  accept(visitor: ShapeVisitor): string;
  area(): number;
}

class Circle implements Shape {
  constructor(public radius: number) {}
  accept(visitor: ShapeVisitor) { return visitor.visitCircle(this); }
  area() { return Math.PI * this.radius ** 2; }
}

class Rectangle implements Shape {
  constructor(public width: number, public height: number) {}
  accept(visitor: ShapeVisitor) { return visitor.visitRectangle(this); }
  area() { return this.width * this.height; }
}

// 3. Visitors para cada operación
class SVGExporter implements ShapeVisitor {
  visitCircle(c: Circle) { return `<circle r="${c.radius}" />`; }
  visitRectangle(r: Rectangle) { return `<rect width="${r.width}" height="${r.height}" />`; }
}

// Agregar nueva operación = nuevo visitor, sin tocar elementos
class MarkdownExporter implements ShapeVisitor {
  visitCircle(c: Circle) { return `Circle (r=${c.radius})`; }
  visitRectangle(r: Rectangle) { return `Rectangle (${r.width}x${r.height})`; }
}

